package takeyouforward;

public class PatternNine {

	public static void main(String[] args) {
		// TODO Auto-generated method stub
		
		int x = 69;

		for(int i=1;i<=5;i++) {
			
			
			for(int k=x;k<=69;k++) {
				
				System.out.print((char)(k));
				
			}
			x--;
			
			System.out.println();
		}
	}

}
